{
  "packet_id": "H6-T02-3",
  "claim_id": "C017",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C017.component",
    "value": "Crossing a predeclared queue-age, backlog-growth, error-rate, resource-pressure, or completion-deadline threshold, or losing telemetry, should trigger restoration of c0 without terminating active exports.",
    "scope": "Conditional safety rollback during the experiment.",
    "provenance": {
      "refs": [
        {"source_id": "P015", "role": "SUPPORT"},
        {"source_id": "P016", "role": "SUPPORT"},
        {"source_id": "P009", "role": "CONTEXT"}
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P015 identifies the predeclared safety thresholds; P016 specifies restoration and protection of active exports; P009 identifies c0 as the baseline concurrency."
    }
  },
  "signal_basis": {
    "component_id": "C017.signal_basis",
    "value": "During the concurrency experiment, a predeclared safety threshold is crossed or telemetry fails.",
    "scope": "The thresholds concern queue age, backlog growth, error rate, resource pressure, and completion deadlines.",
    "provenance": {
      "refs": [
        {"source_id": "P015", "role": "SUPPORT"},
        {"source_id": "P016", "role": "SUPPORT"},
        {"source_id": "P009", "role": "CONTEXT"}
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P015 supplies the threshold categories, P016 supplies the triggering events, and P009 establishes the experimental setting."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C017.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "This supported safety rule requires no additional empirical bridging relation."
    }
  },
  "rationale": "Given the stipulated prerequisites and trigger, restoring the baseline setting is licensed by the experiment's predeclared stopping rule. Threshold violation indicates unacceptable experimental conditions; telemetry failure removes the ability to monitor them. The claim prescribes a bounded precaution without asserting that rollback guarantees recovery or identifies the cause.",
  "uncertainty": "Restoration may take time to affect actual concurrency while active exports finish; this does not undermine the instruction to initiate restoration.",
  "anomalies": []
}
